DEF run m(
  WHILE c(frontIsClear c) w(move w);
  IFELSE c(markersPresent c) i(pickMarker i) ELSE e(turnRight move e);
  WHILE c(leftIsClear c) w(turnLeft move w);
  IFELSE c(markersPresent c) i(pickMarker i) ELSE e(turnRight move e);
  WHILE c(rightIsClear c) w(turnRight move w);
  IFELSE c(markersPresent c) i(pickMarker i) ELSE e(turnLeft move e);
  WHILE c(frontIsClear c) w(move w);
  IFELSE c(markersPresent c) i(pickMarker i) ELSE e(turnRight move e)
)
